changeSet.sql:
create or alter procedure [graph].[Hop_GetImpact] @hopSalt varchar(25), @diagramType int, @direction char(1), -- (F)orward, (B)ackward @predicateUid uniqueidentifier, @hopNumber int, @checkDirection bit, @leafOnly bit as begin set nocount on;
declare @maxRowId int = 0;
if @direction = 'B' begin insert into #links ([Uid], Direction, HopNumber, ProvidedKey, [Key], ID, AssetUid, PredicateId, PredicateUid, PredicateType, [Predicate]) select E.[Uid], @direction, @hopNumber, A.[Key],
utility.GetHash(@hopSalt + '|' + cast(S.ID as varchar(50))), S.ID, S.Uid,
E.PredicateID, E.PredicateUid, E.PredicateType, P.Inverse from graph.AssetNode S, graph.AssetEdge E, graph.AssetNode T, [Predicate] P, #hopAssets A where MATCH(S-(E)->T) and E.PredicateUid = P.[Uid] and (@predicateUid is null OR (@predicateUid is not null AND P.[Uid] = @predicateUid)) and T.ID = A.ID and A.HopNumber = @hopNumber-1 and ( (@checkDirection = 1 and A.Direction = 'B') or (@checkDirection = 0) ) and E.Uid not in (select Uid from #relationsToIgnore); end
if @direction = 'F' begin insert into #links ([Uid], Direction, HopNumber, ProvidedKey, [Key], ID, AssetUid, PredicateId, PredicateUid, PredicateType, [Predicate]) select E.[Uid], @direction, @hopNumber, A.[Key],
utility.GetHash(@hopSalt + '|' + cast(T.ID as varchar(50))), T.ID, T.Uid,
E.PredicateID, E.PredicateUid, E.PredicateType, P.Name from graph.AssetNode S, graph.AssetEdge E, graph.AssetNode T, [Predicate] P, #hopAssets A where MATCH(S-(E)->T) and E.PredicateUid = P.[Uid] and (@predicateUid is null OR (@predicateUid is not null AND P.[Uid] = @predicateUid)) and S.ID = A.ID and A.HopNumber = @hopNumber-1 and ( (@checkDirection = 1 and A.Direction = 'F') or (@checkDirection = 0) ) and E.Uid not in (select Uid from #relationsToIgnore); end
select @maxRowId = max(RowID) from #nodes;
if @maxRowId is null begin set @maxRowId = -1 end
if @diagramType = 2 begin insert into #nodes ([Level], AssetUid, AssetID, [Key], Back, Fore, Icon, AssetTypeID, AssetTypeUid, Class, DisplayValue, Reveal, ActionCount, RelationCounts, UseAsTransformation, IsLeaf, Parsed) select distinct 2 ,A.Uid as AssetUid ,A.ID as AssetID ,L.[Key] ,A.BackColor as Back ,A.ForeColor as Fore ,A.Icon ,A.AssetTypeID ,A.AssetTypeUid ,A.AssetTypeClass as Class ,V.DisplayValue ,0 as Reveal ,0 as ActionCount ,'[]' as RelationCounts ,0 as UseAsTransformation ,1 as IsLeaf ,0 from #links L inner join AssetWithType A on A.ID = L.ID and L.Direction = @direction and L.HopNumber = @hopNumber left join AssetDisplayValue V on V.AssetID = L.ID; end else begin exec graph.Hop_LoadHopHierarchies @hopSalt, @direction, @hopNumber; end
exec graph.Hop_LoadSingleParentHeirarchies @hopSalt, @direction, @hopNumber;
-- This indicates which assets will be used for subsequent hops, as well as which direction. exec graph.Hop_LoadNextHopAssets @direction, @hopNumber, @maxRowId, @leafOnly end

changeSet.rollback:
create or alter procedure [graph].[Hop_GetImpact] @hopSalt varchar(25), @diagramType int, @direction char(1), -- (F)orward, (B)ackward @predicateUid uniqueidentifier, @hopNumber int, @checkDirection bit, @leafOnly bit as begin set nocount on;
declare @maxRowId int = 0;
if @direction = 'B' begin insert into #links ([Uid], Direction, HopNumber, ProvidedKey, [Key], ID, AssetUid, [Segment], PredicateId, PredicateUid, PredicateType, [Predicate]) select E.[Uid], @direction, @hopNumber, A.[Key],
utility.GetHash(@hopSalt + '|' + cast(S.ID as varchar(50))), S.ID, S.Uid, S.Segments,
E.PredicateID, E.PredicateUid, E.PredicateType, P.Inverse from graph.AssetNode S, graph.AssetEdge E, graph.AssetNode T, [Predicate] P, #hopAssets A where MATCH(S-(E)->T) and E.PredicateUid = P.[Uid] and (@predicateUid is null OR (@predicateUid is not null AND P.[Uid] = @predicateUid)) and T.ID = A.ID and A.HopNumber = @hopNumber-1 and ( (@checkDirection = 1 and A.Direction = 'B') or (@checkDirection = 0) ) and E.Uid not in (select Uid from #relationsToIgnore); end
if @direction = 'F' begin insert into #links ([Uid], Direction, HopNumber, ProvidedKey, [Key], ID, AssetUid, [Segment], PredicateId, PredicateUid, PredicateType, [Predicate]) select E.[Uid], @direction, @hopNumber, A.[Key],
utility.GetHash(@hopSalt + '|' + cast(T.ID as varchar(50))), T.ID, T.Uid, T.Segments,
E.PredicateID, E.PredicateUid, E.PredicateType, P.Name from graph.AssetNode S, graph.AssetEdge E, graph.AssetNode T, [Predicate] P, #hopAssets A where MATCH(S-(E)->T) and E.PredicateUid = P.[Uid] and (@predicateUid is null OR (@predicateUid is not null AND P.[Uid] = @predicateUid)) and S.ID = A.ID and A.HopNumber = @hopNumber-1 and ( (@checkDirection = 1 and A.Direction = 'F') or (@checkDirection = 0) ) and E.Uid not in (select Uid from #relationsToIgnore); end
select @maxRowId = max(RowID) from #nodes;
if @maxRowId is null begin set @maxRowId = -1 end
if @diagramType = 2 begin insert into #nodes ([Level], AssetUid, AssetID, [Key], Back, Fore, Icon, AssetTypeID, AssetTypeUid, Class, DisplayValue, Reveal, ActionCount, RelationCounts, UseAsTransformation, IsLeaf, Parsed) select distinct 2 ,A.Uid as AssetUid ,A.ID as AssetID ,L.[Key] ,A.BackColor as Back ,A.ForeColor as Fore ,A.Icon ,A.AssetTypeID ,A.AssetTypeUid ,A.AssetTypeClass as Class ,V.DisplayValue ,0 as Reveal ,0 as ActionCount ,'[]' as RelationCounts ,0 as UseAsTransformation ,1 as IsLeaf ,0 from #links L inner join AssetWithType A on A.ID = L.ID and L.Direction = @direction and L.HopNumber = @hopNumber left join AssetDisplayValue V on V.AssetID = L.ID; end else begin exec graph.Hop_LoadHopHierarchies @hopSalt, @direction, @hopNumber; end
exec graph.Hop_LoadSingleParentHeirarchies @hopSalt, @direction, @hopNumber;
-- This indicates which assets will be used for subsequent hops, as well as which direction. exec graph.Hop_LoadNextHopAssets @direction, @hopNumber, @maxRowId, @leafOnly end

create or alter procedure [graph].[GetImpactHop] @assets dbo.AssetBrowserImpactTable readonly, @self bit, @hopSalt varchar(25), @direction char(1), -- (F)orward, (B)ackward @predicateUid uniqueidentifier, @resourceId int, @isAdmin bit as begin set nocount on;
drop table if exists #assetIds create table #assetIds ([Uid] uniqueidentifier, ID bigint, Class int, [Key] varchar(50)) create index ix_TempAssetIds on #assetIds (ID asc)
drop table if exists #links; create table #links ( [Uid] uniqueidentifier, Direction char(1), ProvidedKey varchar(50), [Key] varchar(50), ID bigint, [AssetUid] uniqueidentifier, [Path] nvarchar(2500), [Segment] xml, PredicateId int, PredicateUid uniqueidentifier, [Predicate] nvarchar(250), PredicateType int);
drop table if exists #nodes create table #nodes ( [Level] int, AssetUid uniqueidentifier, AssetID bigint, [Key] varchar(50), ParentID bigint null, ParentKey varchar(50), Back varchar(25), Fore varchar(25), Icon varchar(50), AssetTypeID int, AssetTypeUid uniqueidentifier, Class int, DisplayValue nvarchar(500), Reveal int, ActionCount int, RelationCounts varchar(max), OwnerCounts varchar(max), UseAsTransformation bit null, IsLeaf bit, IsSubjectInTransformation bit null, HasAssetReadAccess bit null); create index ix_Temp_Nodes_AssetID on #nodes ([AssetID] asc); create index ix_Temp_Nodes_AssetID_IsLeaf on #nodes ([AssetID] asc, IsLeaf asc); create index ix_Temp_Nodes_AssetTypeID_IsLeaf on #nodes ([AssetTypeID] asc, IsLeaf asc);
insert into #assetIds select distinct A.Uid, A.ID, T.[Class], O.[Key] from Asset A inner join @assets O on O.Uid = A.Uid inner join AssetType T on T.ID = A.AssetTypeID
if @self = 1 -- SELF begin insert into #links (Direction, [Key], ID, AssetUid, [Path], [Segment]) select @direction, A.[Key],
N.ID as ToID, N.Uid as ToUid, N.[Path] as ToPath, N.Segments as ToSegment
from graph.AssetNode N, #assetIds A where N.ID = A.ID; end else -- IMPACT begin if @direction = 'B' begin insert into #links ([Uid], Direction, ProvidedKey, [Key], ID, AssetUid, [Path], [Segment], PredicateId, PredicateUid, PredicateType, [Predicate]) select E.[Uid], @direction, A.[Key],
utility.GetHash(@hopSalt + '|' + cast(S.ID as varchar(50))), S.ID, S.Uid, S.[Path], S.Segments,
E.PredicateID, E.PredicateUid, E.PredicateType, P.Inverse from graph.AssetNode S, graph.AssetEdge E, graph.AssetNode T, [Predicate] P, #assetIds A where MATCH(S-(E)->T) and E.PredicateUid = P.[Uid] and P.[Uid] = @predicateUid and T.ID = A.ID; end else begin insert into #links ([Uid], Direction, ProvidedKey, [Key], ID, AssetUid, [Path], [Segment], PredicateId, PredicateUid, PredicateType, [Predicate]) select E.[Uid], @direction, A.[Key],
utility.GetHash(@hopSalt + '|' + cast(T.ID as varchar(50))), T.ID, T.Uid, T.[Path], T.Segments,
E.PredicateID, E.PredicateUid, E.PredicateType, P.Name from graph.AssetNode S, graph.AssetEdge E, graph.AssetNode T, [Predicate] P, #assetIds A where MATCH(S-(E)->T) and E.PredicateUid = P.[Uid] and P.[Uid] = @predicateUid and S.ID = A.ID; end end;
insert into #nodes (AssetUid, AssetID, [Key], Back, Fore, Icon, AssetTypeID, AssetTypeUid, Class, DisplayValue, Reveal, ActionCount, RelationCounts, UseAsTransformation, IsLeaf, HasAssetReadAccess) select distinct A.Uid as AssetUid ,A.ID as AssetID ,L.[Key] ,A.BackColor as Back ,A.ForeColor as Fore ,A.Icon ,A.AssetTypeID ,A.AssetTypeUid ,A.AssetTypeClass as Class ,V.DisplayValue ,0 as Reveal ,0 as ActionCount ,'[]' as RelationCounts ,0 as UseAsTransformation ,1 as IsLeaf ,case when exists(select * from dbo.AssetTypesUserCantRead(@resourceId) where assettypeid = A.AssetTypeId) then 0 when exists(select * from dbo.AssetsByTypeUserCantRead(@resourceId, A.AssetTypeId) where A.id = assetid) then 0 else @isAdmin end as HasReadAccess from #links L inner join AssetWithType A on A.ID = L.ID left join AssetDisplayValue V on V.AssetID = L.ID;
-- Get type-based parent for single-level asset hierarchies above. insert into #nodes ([Level], AssetUid, AssetID, [Key], ParentID, ParentKey, Back, Fore, Icon, AssetTypeID, AssetTypeUid, Class, DisplayValue, Reveal, ActionCount, RelationCounts, UseAsTransformation, HasAssetReadAccess) select 1 as [Level], CAST(0x0 AS UNIQUEIDENTIFIER) as AssetUid, 0 as AssetID, utility.GetHash(@hopSalt + '|' + cast(n.AssetTypeUid as varchar(50))) as [Key], null as ParentID, null as ParentKey, n.Back, n.Fore, n.Icon, n.AssetTypeID, n.AssetTypeUid, n.Class, t.Name as DisplayValue, n.Reveal, 0 as ActionCount, n.RelationCounts, t.UseAsTransformation, 0 as HasAssetReadAccess -- 0 as this is AssetType from #nodes n inner join #links l on l.[Key] = n.[Key] and n.[ParentKey] is null inner join AssetType t on t.ID = n.AssetTypeID left join #nodes c on c.ParentID = n.AssetID where c.AssetID is null;
update t set t.ParentID = t.AssetTypeID, t.ParentKey = utility.GetHash(@hopSalt + '|' + cast(t.AssetTypeUid as varchar(50))), t.[Level] = 2 from #nodes t inner join #links l on l.[Key] = t.[Key] and t.[ParentKey] is null left join #nodes c on c.ParentID = t.AssetID where c.AssetID is null;
-- Get action counts update R set R.ActionCount = coalesce( ( select count(1) as ActionCount from Issue I inner join Asset A on A.Object = I.Object and A.ObjectID = I.ObjectID where I.CompletedOn is null and exists (select 1 from workflow.Item where Object = 'Issue' and ObjectID = I.ID) and A.ID = R.AssetID group by A.Uid ), 0) from #nodes R;
-- Get impact badges update R set R.RelationCounts = coalesce( ( select [Predicate], ID as PredicateID, Uid as PredicateUid, Direction, count(1) as [Count] from ( select P.Name as [Predicate], P.ID, P.Uid, 1 as Direction from graph.AssetNode S, graph.AssetEdge E, graph.AssetNode T, [Predicate] P where MATCH(S-(E)->T) and S.ID = R.AssetID and P.ID = E.PredicateID --and E.PredicateType in (6,7,9,14) union all select P.Inverse as [Predicate], P.ID, P.Uid, 2 as Direction from graph.AssetNode S, graph.AssetEdge E, graph.AssetNode T, [Predicate] P where MATCH(S-(E)->T) and T.ID = R.AssetID and P.ID = E.PredicateID --and E.PredicateType in (6,7,9,14) ) O group by [Predicate], ID, Uid, Direction for json path ), '[]' ) from #nodes R;
-- Get owner badges update R set R.OwnerCounts = coalesce( ( select ResponsibilityTypeName as ResponsibilityType, ResponsibilityTypeID, '[' + string_Agg(ResourceID, ',') + ']' as UsersList, count(1) as [Count] from ( select ResponsibilityTypeName, ResponsibilityTypeID, ResourceID from ResponsibilityDetail where ( AssetID = R.AssetID OR (AssetID = 0 and AssetTypeID = R.AssetTypeID) ) and IsVisible = 1 group by ResponsibilityTypeName, ResponsibilityTypeID, ResourceID ) O group by ResponsibilityTypeName, ResponsibilityTypeID for json path ), '[]' ) from #nodes R;
update #nodes set OwnerCounts = '[]', IsLeaf = 0 where IsLeaf is null;
-- Return to caller select distinct assetUid, assetId, [key], parentId, parentKey, back, fore, icon, assetTypeId, assetTypeUid, class, displayValue, reveal, actionCount, relationCounts, ownerCounts, useAsTransformation, isSubjectInTransformation, isLeaf, hasAssetReadAccess, [level] from #nodes order by [Level];
select [uid] ,case Direction when 'F' then ProvidedKey else [Key] end as subjectKey ,case Direction when 'F' then [Key] else ProvidedKey end as objectKey ,predicateId ,predicateUid ,[predicate] ,predicateType from #links where [Key] is not null and ProvidedKey is not null; end
